import os
MODULES=['pcc_neuro_ext93','pcc_pediatric_neuro_ext82','pcc_pediatric_surg_ext82']
FUNCS={
'pcc_neuro_ext93':[('MovementDisorderClinicExt','0.15 + Number(input.durationMin||30)*0.01 + Number(input.udysrs||30)*0.01 + Number(input.complex||1)*0.15'),('BotulinumToxinDosingExt','0.2 + Number(input.muscleNum||6)*0.05 + Number(input.doseUnits||400)*0.0005 + Number(input.guide||1)*0.15'),('DBSProgrammingClinicExt','0.18 + Number(input.tuneTime||60)*0.005 + Number(input.contacts||4)*0.05 + Number(input.optimization||80)*0.005'),('ParkinsonMedicationMgmExt','0.2 + Number(input.levoEquiv||600)*0.0003 + Number(input.onTime||70)*0.005 + Number(input.dyskinesia||1)*0.1'),('AtaxiaRefMgmExt','0.15 + Number(input.falls||3)*0.05 + Number(input.ataxiaScl||15)*0.02 + Number(input.balance||70)*0.005'),('DystoniaEvalExt','0.15 + Number(input.distribution||3)*0.1 + Number(input.duration||5)*0.05 + Number(input.score||30)*0.01'),('TremorEvalExt','0.15 + Number(input.frequency||5)*0.05 + Number(input.amplitude||2)*0.1 + Number(input.disability||30)*0.01'),('HuntingtonClinicExt','0.2 + Number(input.tfcScore||10)*0.05 + Number(input.uhdrs||30)*0.01 + Number(input.cag||45)*0.02'),('TouretteClinicExt','0.15 + Number(input.yaleScore||20)*0.02 + Number(input.pheno||3)*0.05 + Number(input.behaviorTherapy||1)*0.2'),('NeurodegenerativeCarePlanExt','0.18 + Number(input.moca||25)*0.02 + Number(input.adlScore||75)*0.005 + Number(input.support||1)*0.15')],
'pcc_pediatric_neuro_ext82':[('PediatricMovementDisorderExt','0.15 + Number(input.durationMin||30)*0.01 + Number(input.score||30)*0.01 + Number(input.complex||1)*0.15'),('PediatricBotulinumDosingExt','0.2 + Number(input.muscleNum||4)*0.05 + Number(input.units||200)*0.0005 + Number(input.guide||1)*0.15'),('PediatricDBSClinicExt','0.18 + Number(input.tuneTime||45)*0.005 + Number(input.contacts||2)*0.05 + Number(input.optimization||70)*0.005'),('PediatricCPMedMgmExt','0.15 + Number(input.spasticity||3)*0.1 + Number(input.baclofen||30)*0.01 + Number(input.physio||3)*0.1'),('PediatricAtaxiaMgmExt','0.15 + Number(input.falls||3)*0.05 + Number(input.scale||20)*0.02 + Number(input.balance||60)*0.005'),('PediatricDystoniaEvalExt','0.15 + Number(input.distrib||3)*0.1 + Number(input.duration||3)*0.05 + Number(input.score||30)*0.01'),('PediatricTremorEvalExt','0.15 + Number(input.freq||5)*0.05 + Number(input.amp||1)*0.2 + Number(input.disability||20)*0.01'),('PediatricHuntingtonExt','0.2 + Number(input.ageOnset||10)*0.03 + Number(input.familyHist||1)*0.15 + Number(input.cag||45)*0.02'),('PediatricTouretteExt','0.15 + Number(input.ygtts||20)*0.02 + Number(input.add||1)*0.2 + Number(input.behav||3)*0.05'),('PediatricNeurodegenerativeCareExt','0.18 + Number(input.develop||80)*0.005 + Number(input.adl||75)*0.005 + Number(input.support||1)*0.15')],
'pcc_pediatric_surg_ext82':[('PediatricBotoxInjectionSurgExt','0.2 + Number(input.muscles||5)*0.05 + Number(input.dose||150)*0.001 + Number(input.guide||1)*0.15'),('PediatricDBSPedImplantSurgExt','0.18 + Number(input.age||8)*0.02 + Number(input.weight||25)*0.01 + Number(input.target||2)*0.15'),('PediatricIntrathecalBaclofenExt','0.2 + Number(input.pumpRefill||3)*0.05 + Number(input.dose||300)*0.0005 + Number(input.sideEffects||1)*0.15'),('PediatricSelectiveDorsalRhoExt','0.18 + Number(input.age||6)*0.02 + Number(input.levels||4)*0.05 + Number(input.outcome||1)*0.15'),('PediatricRhizotomySurgExt','0.2 + Number(input.age||5)*0.04 + Number(input.levels||6)*0.05 + Number(input.outcome||1)*0.15'),('PediatricDeepBrainStimLeadExt','0.18 + Number(input.age||9)*0.02 + Number(input.target||1)*0.2 + Number(input.effect||1)*0.15'),('PediatricDBSBatteryReplaceExt','0.15 + Number(input.lifeYears||5)*0.04 + Number(input.complications||1)*0.1 + Number(input.outcome||1)*0.15'),('PediatricPeripheralNerveExt','0.15 + Number(input.age||7)*0.04 + Number(input.nerves||2)*0.1 + Number(input.outcome||1)*0.15'),('PediatricTendonLengtheningExt','0.18 + Number(input.age||5)*0.04 + Number(input.tendons||3)*0.05 + Number(input.outcome||1)*0.15'),('PediatricRehabAfterSurgExt','0.15 + Number(input.intensity||3)*0.1 + Number(input.weeks||8)*0.04 + Number(input.gain||10)*0.04')]}
for m in MODULES:
    d=f'./{m}'
    os.makedirs(d, exist_ok=True)
    eng=f'// filepath: pcc/{m}/{m}_engine.js\n// {m} engine (deterministic)\nmodule.exports.version=\'v3.192.0\';\nmodule.exports.module=\'{m}\';\nmodule.exports.functions={{}};\n'
    for fn,body in FUNCS[m]:
        eng+=f'module.exports.functions[\'{fn}\']=function(input){{const score=Math.round(({body})*100)/100;return{{version:\'v3.192.0\',module:\'{m}\',function:\'{fn}\',input,score,ts:new Date().toISOString()}};}};\n'
    eng+=f'\n// TS: v3.192.0\n'
    open(f'{d}/{m}_engine.js','w',encoding='utf-8').write(eng)
    test=f'// filepath: pcc/{m}/{m}_test.js\nconst {{functions:F}}=require(\'./{m}_engine\');let pass=0;for(const fn of Object.keys(F)){{const r=F[fn]({{}});if(typeof r.score===\'number\'&&r.score>=0&&r.score<=1.5)pass++;else console.error(\'FAIL\',fn,r);}}console.log(\'{m} unit:\',pass,\'passed\');if(pass!==10)process.exit(1);\n'
    open(f'{d}/{m}_test.js','w',encoding='utf-8').write(test)
    itest=f'// filepath: pcc/{m}/{m}_integration_test.js\nconst {{functions:F}}=require(\'./{m}_engine\');let pass=0;const samples=[{{value:1}},{{value:2}},{{value:3}},{{value:4}},{{value:5}}];for(const fn of Object.keys(F)){{for(const s of samples){{const r=F[fn](s);if(r&&typeof r.score===\'number\')pass++;}}}}console.log(\'{m} integration:\',pass,\'passed\');if(pass!==50)process.exit(1);\n'
    open(f'{d}/{m}_integration_test.js','w',encoding='utf-8').write(itest)
    routes=f'// filepath: pcc/{m}/{m}_routes.js\nconst express=require(\'express\');const {{functions:F}}=require(\'./{m}_engine\');const {{authenticate}}=require(\'../middleware\');const router=express.Router();\nrouter.get(\'/list\',(_req,res)=>res.json({{module:\'{m}\',version:\'v3.192.0\',functions:Object.keys(F)}}));\nrouter.post(\'/call/:fn\',(req,res)=>{{const fn=req.params.fn;if(!F[fn])return res.status(404).json({{error:\'not found\'}});const r=F[fn](req.body||{{}});res.json(r);}});\nrouter.post(\'/record\',(req,res)=>{{const {{fn,payload,decisionId}}=req.body||{{}};if(!F[fn])return res.status(404).json({{error:\'not found\'}});const r=F[fn](payload||{{}});res.json({{decisionId,...r}});}});\nmodule.exports=router;\n'
    open(f'{d}/{m}_routes.js','w',encoding='utf-8').write(routes)
    sql=f'-- pcc/{m}/{m}_up.sql\nIF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N\'[dbo].[{m}]\') AND type = \'U\')\nBEGIN\nCREATE TABLE [dbo].[{m}] (\n  [id] INT IDENTITY(1,1) PRIMARY KEY,\n  [tenant_id] NVARCHAR(64) NOT NULL,\n  [version] NVARCHAR(16) NOT NULL,\n  [module] NVARCHAR(64) NOT NULL,\n  [function] NVARCHAR(128) NOT NULL,\n  [input] NVARCHAR(MAX) NULL,\n  [score] DECIMAL(6,2) NULL,\n  [ts] DATETIME2 DEFAULT SYSUTCDATETIME()\n);\nEND\n'
    open(f'{d}/{m}_up.sql','w',encoding='utf-8').write(sql)
    print(f'{m}: 5 files written')
print('P3-IL v3.192.0: 16 files written')
